from pathlib import Path
from collections import Counter
import json,re

O=Path(__file__).resolve().parents[1]
B={b['id']:b for b in json.loads((O/'_source/blocks.json').read_text())}
edits=[]
def edit(i,title,problem,reason,benefit,text):
    bid=f'B{i:04d}';b=B[bid]
    assert 526<i<781 and b['kind']=='p' and not b['style_name'].startswith('heading')
    assert text!=b['text']
    assert re.findall(r'\[\d+\]',text)==re.findall(r'\[\d+\]',b['text']),(bid,'citations')
    nums=lambda t:Counter(re.findall(r'\d+(?:\.\d+)?',t))
    assert nums(text)==nums(b['text']),(bid,'numbers',nums(text)-nums(b['text']),nums(b['text'])-nums(text))
    heads=[x for x in B.values() if 526<=x['index']<=i and x['style_name'].startswith('heading')]
    edits.append({'block_id':bid,'title':title,'section':heads[-1]['text'],'old_text':b['text'],'new_text':text,'problem':problem,'reason':reason,'benefit':benefit})

edit(527,'章首：用研究问题串联章节内容','原文主要预告介绍顺序，组件修改与关系处理这一核心问题出现较晚。','先明确本章研究的修改对象和依赖问题，再说明候选、接受准则和求解的关系。','章节由问题引出方法，读者能理解后续各节为何按此顺序展开。','第三章讨论训练文本改写后的监督继承，本章转向原文保持不变时的预测图修正，重点研究组件修改后如何同步处理受影响的关系。下文从候选与初始图出发，说明对象评分和接受准则，再通过完整事务解释依赖闭合，最后介绍局部与全局求解及相应实验。')
edit(529,'问题提出：明确两类单独接受的风险','“仅依据……先行提交”和“仅依据……接受”的操作对象略显含混。','分别点明组件修改的提交和整图修改的接受，并把各自遗漏的代价接在对应操作之后。','读者能分清关系身份失效和均分分母变化是两个不同问题。','组件的边界或类型改变后，引用该端点的完整关系对象身份也随之改变。若只依据组件置信度提交修改，就可能遗漏整条关系失效的代价；若只依据图中的平均覆盖分数接受修改，又可能把分母变化造成的分数上升误作收益。')
edit(530,'方法定位：交代继承流程与追加阶段','继承部分、新增阶段和子程序缩写集中出现，层级关系不够醒目。','先给出统一接受规则，再按基线、完整配置和局部子程序逐层定义。','I0、I1、R_DC与BR-J的关系更清楚，便于后文正确归属实验收益。','MCR-BR已支持类型与跨度修改[34]。本章在固定候选宇宙和完整对象评分的前提下，将冲突闭合、关系重建、分项效用及编辑预算纳入统一接受规则。基线I0沿用多候选生成与重排序、共同合法化和BR-O；完整配置I1从I0最终合法图G0出发，追加依赖闭合修正R_DC及固定路由。BR-J仅指追加阶段中的集合局部子程序。实验分别评价共同接受、集合动作和求解路径的作用。')
edit(531,'记录设计：说明冻结快照的核对用途','“关联”“绑定运行身份”等表达较抽象，记录之间为何需要对应没有直接展开。','明确统一快照用来逐项核对哪些记录，再说明不同案例为何分别记录运行身份。','证据记录的用途更具体，也能自然引出主条件与独立诊断的区别。','本章以统一的冻结快照为依据，逐项核对对象评分、候选来源、求解返回状态、事务差集和严格计数。真实文档上的参考事务与独立CPU规则案例分别记录运行身份，以区分主条件结果和附加诊断。')
edit(535,'相关研究：把比较重点落在共同接受条件','“以……为前提”的限定较密集，本文究竟比较什么可以更直接。','将固定条件与待比较问题分开，保留隐含前提和局部搜索的范围限定。','本文关注的是端点与关系的联合决策，和已有工作的衔接更具体。','已有研究通过结构解析和整数规划联合处理组件与关系[46]，抽取修正与论辩重构研究也提出了相关机制[43][44]。本文固定原文、候选和评分，重点比较端点变化与关系重建共同进入接受条件时的结果。方法不生成隐含前提，局部搜索本身也不被预设为优势。')
edit(537,'候选入口：解释初始选择与后续修正的分工','“竞争结构”“不同决策任务”较概括，两个阶段使用候选的方式可更明确。','以选择初始图和限定可访问对象分别说明两个阶段的目的。','读者能理解共享候选来源并不意味着两个阶段执行同一种选择。','候选生成承担两项任务：为初始图选择提供可比较的完整结构，并限定后续修正能够访问的对象。初始选择沿用MCR接口；修正开始前，则将多次生成和补充提议中的对象汇总为固定候选宇宙。两阶段共享候选来源，分别确定初始结构与可修改范围。')
edit(541,'生成与解析：把组件保留条件和关系失败分开','关系生成、解析失败、组件保留和成本记录由多个分号相连，条件容易混读。','按生成、解析和记录顺序组织，明确关系失败不自动撤销已通过检查的组件。','不同对象的失败边界更清楚，后处理记录也有明确用途。','每个组件包含原文跨度与类型。关系生成器在固定的 Ck 上预测关系，形成 Gk=Ck,Rk，期间不得更改组件。关系字段解析失败时，单独记录该失败，已经通过坐标、类型及重叠检查的组件仍保留为候选；失败调用的开销计入总成本。同一候选的原始输出、解析结果和坐标转换均予保留，用于区分生成模型预测与后处理结果。')
edit(543,'继承流程：明确三个图状态的先后关系','连续使用“得到”“再经”串接多个阶段，图状态与输出身份需要读者反向对应。','按重排序、合法化和BR-O处理的顺序逐一写明输出，再引出追加修正。','Grank、Gpre与G0不易混淆，独立追加预算的起点更清楚。','初始重排序沿用MCR的加权形式，输出Grank；共同合法化将其转为Gpre。随后执行继承的BR-O处理，并复核合法性，得到I0最终输出G0。完整I1从G0出发执行追加修正R_DC，该阶段的预算独立记账。重排序的加权形式为：')
edit(548,'合法化：区分中间状态、失败出口与最终输出','验证分量、同分规则、合法化和阶段账本连续出现，中间状态定位略弱。','按判分、合法化、基线终止和记录顺序展开，把Gpre的身份接在最终输出后。','合法化成功不再容易被误读为I0流程已完成。','全部可解析性、跨度、类型及引用检查通过时，Eval取1，否则取0；无环检查仅在协议要求时启用。同分候选按生成槽位选择。共同合法化仅处理Grank，执行无歧义坐标规范化、同身份去重和ID重排，得到Gpre；遇到歧义ID、越界、非法类型或未消除冲突时返回失败。BR-O从该中间状态出发，按继承规则终止，并通过合法性复核后形成G0。因此，Gpre不计作I0终态。重排序与合法化、BR-O及追加修正R_DC分别保存阶段标识和成本。')
edit(549,'评分动机：将分母变化与接受目标联系起来','原文条件完整，但从初始重排序转到修正评分的原因可以更连贯。','先指出共享验证信号和变化分母，再解释为何原评分仅保留在初始选择中。','读者能沿同一问题理解固定计数效用的必要性。','覆盖与连贯性共用 pr，不能视为相互独立的证据。覆盖节点数和当前边数还决定均分的分母，因此删除低分对象或改变组件类型可能提高平均分，却未必提高真实准确率。基于这一限制，本章保留上述评分用于初始候选选择，另为允许组件变化的修正阶段定义接受目标。')
edit(551,'跨度保护：按来源、裁剪与资源失败组织','受保护对象、补充提案和资源例外挤在一个长段内，G0保留规则难以快速定位。','先交代保护集合和补充集合，再集中说明去重、数量超限及失败回退。','哪些对象可裁剪、哪些必须保留更加明确，基线保护的目的也更清楚。','追加修正开始前，先构建固定跨度集合U。受保护部分收集I0最终合法图G0及各候选输出中可独立解析的合法组件跨度，也包含BR-O引入并最终保留在G0中的跨度。对象先去重，G0对象不按概率阈值裁剪。补充部分由原生跨度头与类型提案提供；边界规则扩展默认关闭，仅在可选消融中启用，候选数量增长不直接视为覆盖提升。两部分分别计数。保护对象数量超过补充上限时仍保留G0；若总资源无法容纳保护部分，则明确返回候选构造失败并保留G0，避免隐式改变继承基线。')
edit(553,'候选记录：明确保护限制与新增边界','“隐式扩张候选空间”偏概括，记录对象与禁止操作之间的关系可更直接。','先说明受保护跨度不参与补充裁剪，再明确新增跨度也必须遵守统一规则。','保护对象和补充对象的管理边界更易核对。','受保护跨度不受补充长度和数量上限裁剪，候选的保护来源、补充来源及两者重叠数量分别登记。新增跨度仍须遵守统一的去重和坐标规则，不能通过改变这些规则扩张候选空间。')
edit(554,'带类型候选：分开默认配置、消融与身份定义','类型数量、集合表达、全类型消融和身份规则集中呈现，层次切换较快。','先给出默认候选构成，再说明全类型消融和选择约束，最后落到语义身份。','读者能区分候选生成范围、选择状态及对象去重依据。','每个补充跨度默认保留类型头排名前2的原生类型，受保护对象的类型则全部保留。记候选类型集合为T*u，带类型候选构成V={u,t:t∈T*u}。全类型展开作为独立消融，与默认有限候选池分别报告。NULL表示不选择，同一跨度至多选择一个类型；组件兼容性按语料协议逐对判定。对象的语义身份由规范跨度和类型确定，显示ID不参与评分。完整键与坐标映射见附录A.6。')
edit(555,'完整身份：解释字符对象与派生表示的关系','“完整键”“token范围”与各类检查连续罗列，统一身份的用途可更清楚。','按跨度定义、派生表示和关系键逐层展开，明确相同token外包范围不能合并字符对象。','字符精确匹配为何贯穿候选、评分与评价更容易理解。','这里u表示由文档版本和字符半开区间组成的规范跨度(d,b,e)，带类型候选(u,t)因而展开为(d,b,e,t)。token范围与残差仅用于派生表示和无损往返，即使token外包区间相同，也不合并不同的字符对象。关系键进一步由完整源组件键集合、目标组件键及原生标签构成。候选去重、评分缓存、冲突检查和严格评价均使用这一身份。')
edit(558,'反向事务：先说明入队条件，再说明缺失处理','冻结池裁剪、反向条件、多源例外和记录要求由长句连续承载。','以二元反向事务的必要条件为中心，依次说明缺槽位、纯删除和多源关系的处理。','“未入队”和“评估后拒绝”更容易区分，也不会把单向重选误作反向操作。','关系池枚举当前无边的有向槽位，但独立裁剪不保证正逆方向同时保留。二元反向事务只在正逆两个完整槽位均位于冻结池中、当前端点存在且两方向合法时枚举，并将两槽位的全部合法标签共同纳入。逆向槽位缺失记为候选范围限制，搜索期间不补入池外关系；已有关系的纯删除仍可单独枚举。多源超边没有定义多目标反向操作，因此不进入反向队列。初始保护、来源数量、去重、裁剪、未入队及评估后拒绝分别记录，候选池与分数在一次搜索前冻结。')
edit(559,'语料约束：把表示差异落实到关系构造','两种关系表示的禁止转换与标签定义的限制连续出现，可更突出协议依据。','先按语料说明原生表示，再交代为何同名标签仍需要各自定义。','读者能理解不能任意拆合超边，也不能跨语料直接套用标签解释。','各语料分别登记原生约束。CasiMedicos-Arg仅允许单源二元关系，CDCP则保留完整源集合及其连续性要求。多个前提支持同一目标时，二元语料使用多条关系；CDCP的联合源范围仍作为一个完整对象，不能在两种表示之间任意拆合。即使关系标签或组件类型同名，标注准则也未必相同，评分提示和严格评价均依据相应语料的定义（A.3及D.3）。')
edit(560,'资源预检：区分最终池上限与前置计算成本','“最终补充槽位上限”与若干较小提案上限相邻，容易误读为同一层级的数量限制。','从最终裁剪不能限制前置开销这一原因出发，按提案预算、预检和失败返回展开。','不同上限各自控制哪个阶段更明确，失败后计数与成本保留也可直接查阅。','即使最终补充槽位上限为4096，裁剪前的提案、枚举和评分仍可能消耗过多资源。因此，默认入口采用有限原生提案：补充跨度上限为64，每跨度保留前2类型；CDCP模型提案最多64个，连同规则补充共不超过256个完整源组与目标，受保护对象另计。构建时先流式检查实际合法槽位数，以50000为资源上限。超限即明确返回候选构造失败，并保留I0终态G0、金标分母及已耗成本。')
edit(562,'裁剪与比较：说明统一候选池的作用','裁剪记录、覆盖遗漏和公平比较连续切换，三者的联系可以更紧密。','先写裁剪及冻结规则，再说明有限源组的覆盖风险，最后交代两条路径共用条件。','候选范围造成的限制与求解路径造成的差异更容易分开分析。','资源裁剪依据冻结的提案分或对象分执行，分别记录保护对象、补充对象、裁前／裁后数量及多源覆盖，候选质量判断在冻结后进行。有限源组可能遗漏正确的联合源，因而需要与全类型展开或扩大源组预算进行覆盖对照。比较局部与全局求解时，两者共享同一最终候选池和评分快照，不为任一路径单独调整这些输入。')
edit(565,'评分过渡：从状态可比性引出分项门','“评价口径漂移”“方向的代理代价交换”抽象程度较高。','直接指出对象数量和结构变化为何要求固定评分，再说明分项门约束什么交换。','读者无需先理解抽象名词即可把握计数效用和分项门的分工。','联合事务需要在不同搜索状态之间比较收益。为使组件数、关系数和图结构变化时仍保持同一评价口径，本章在搜索前冻结完整对象的得分，以固定计数效用衡量对象的新增与删除。分项接受门则限制以组件代理效用的下降换取关系增益，或作相反方向的交换。')
edit(569,'评分对象：强调完整关系的正确性条件','组件头和关系头的输入、监督及正例条件连写，完整对象概率的含义可以更突出。','分开输入说明与正例判定，再以金标端点分类任务作为边界。','关系类别预测正确不再容易与完整关系对象正确混淆。','组件头根据跨度与全文表示预测NULL/类型分布。关系头输入端点跨度表示、待核查端点类型、方向、关系标签及全文证据，通过二元监督判断整个关系对象是否正确。只有端点跨度、端点类型和关系标签均精确匹配时，该对象才构成正例。因此，仅在金标准端点上训练得到的关系分类准确率，不能替代完整对象正确性概率。')
edit(571,'缺失评分：按冻结条件、评估入口和结论边界展开','这一长段同时承担固定评分定义、缺分处理与校准限定，读者容易漏掉事务准入条件。','先说明对象得分为何跨状态不变，再明确必须有分数的对象范围，最后交代差分和校准边界。','低置信度与未知评分的区别更清楚，也更容易核对某个事务能否进入评估。','搜索开始前，同一文档的文本表示、模型版本、校准参数和候选得分均被冻结。缓存绑定完整语义键，不以显示编号代替端点身份；当前图的度数、已选边数和动态重编码不进入 q，使同一对象在不同搜索状态中保持相同分值。低置信度与未取得评分分别处理：缺失、非有限或显式未评估的值均保留为缺失状态。只有拟删除或加入的组件，以及最小合法化扩域后的事务关系空间都具有有效分数，提议才进入评估。事务外未变对象在差分中相消，变化对象的接受判断不使用任意默认值。上述要求补充输入完整性检查，不改变固定效用、依赖闭合及接受门；启发式模型能够输出数值，也不代表其正确性已经校准。主评价缺分率及独立缺分检查见4.6.3和附录B。')
edit(572,'OOF监督：说明错误来源与分组隔离','“接触实际推理错误”较口语化，折内训练限制与共同候选池目的还可更紧密。','以评分器的监督需求为起点，按分组、生成、精确标记和共同池比较展开。','评分器为何需要真实候选错误，以及如何避免只适应某个生成器，更易理解。','评分器的监督应包含实际推理产生的错误，不能只使用人工构造的容易负例。训练部分按源文档分组进行out-of-fold（OOF）候选生成。对每一持出折，生成器与跨度头均不使用该折文档及其增强变体训练，再为持出文档生成完整候选、边界扰动和关系组合。候选与训练金标准精确匹配后，形成评分监督。比较两种训练方法时，OOF池同时纳入两类生成器的候选并保留来源，以减少评分器仅适应其中一类的偏差。')
edit(575,'开发选择：按筛选、优化和回退陈述','参数网格、损失约束和并列规则紧密排列，选择顺序可更清楚。','保留全部参数值，依次解释经验筛选、目标最大化、并列处理和全部失败的返回。','策略选择过程可直接复述，测试标签的用途边界也更明确。','策略在按源文档独立划分的策略集上选择。AAEC固定κR=1；CDCP联合检查κR∈{0.5,1.0}与δ∈{0.01,0.05,0.10,0.20}。先剔除原TP损失率超过5%的条件，再从其余条件中选择汇总关系F1最高者；并列时依次取较大的κR和δ。若全部条件均不合格，则保持I0输出。完整开发网格保存在risk_grid_v9.json中，测试标签不参与门限选择。')
edit(576,'适用边界：区分策略限制、缺分与评分失准','参数共用、逐文档保证和两类评分问题连续出现，处理机制容易混为一谈。','先限定开发约束的保证范围，再交代固定参数和两类评分异常的不同处理。','不把有效数值误作可靠概率，也不把汇总经验筛选误作逐文档保证。','开发约束是在有限数据上的经验选择，不保证每篇测试文档的TP均保留或F1均不下降。δ与分项代价κ在评价前按语料固定，由局部和全局路径共用，不能临时根据测试文档选择较高分结果。评分缺失时保留未知状态，并拒绝受影响事务；分数有效但不准确时，则通过OOF训练、自然分布校准和对象诊断评估并缓解误差。')
edit(583,'效用推导：明确常数项与候选池外遗漏','“不可改变的部分”指向略宽，池外漏检与风险解释之间的关系可更直接。','先说明固定项为何不影响图选择，再指出固定候选池使池外漏检无法通过搜索改变。','公式的优化含义和覆盖局限在同一逻辑下得到解释。','第一项不随预测图变化，因此最大化该效用等价于最小化固定误检与漏检代价的条件期望风险。推导只依赖期望的线性性，不要求对象正确性相互独立。候选池外真实对象造成的漏检也无法通过池内搜索改变，因而须将池内错误与池外遗漏分别分析。')
edit(584,'代理目标：将风险解释与F1最优性分开','多个否定判断连续出现，读者需要自行整理每个判断所对应的理论范围。','先定义所用目标，再说明边际概率及已有阈值结论的适用限制，最后界定贡献归属。','代理目标有何依据、为何不能据此声称F1最优，更容易连贯理解。','本章使用代价敏感代理目标，不直接优化期望F1。一般F1决策涉及真实标签数量与对象正确事件之间的依赖，普通边际概率通常不足以确定最优决策[41]。特定条件下得到的F1最优阈值结论，也不能通过代入任意基线F1直接用于这里的结构搜索[42]。上述风险恒等式用于解释评分的代价含义，不单独作为基础理论创新。')
edit(587,'接受门：把各门的作用与代价相邻说明','“两个分项门”与“总效用门”的作用连写，保守性的实际含义可以更直接。','分别说明分项门限制跨类别交换、总门排除等分，再保留真实效果不保证的边界。','接受条件的设计目的和可能拒绝有益替换的代价都更清楚。','两个分项门限制以某类代理效用下降换取另一类增益，总效用门则排除等分修改。这些保守条件可能拒绝真实有益的结构替换，也不能保证真实组件或关系F1不下降。数值容差与正间隔 δ 在评价前固定，不随测试结果调整。')
edit(588,'编辑成本：区分预算用途、阶段和累计口径','成本公式、少改优先、阶段隔离与累计记录密集陈述，读者容易把成本当成效用惩罚。','先定义成本及类型变化的计费，再明确成本用途，最后区分阶段与累计/净变化。','编辑预算为何不会给接近初始图额外奖励，以及反复编辑如何计数，均更易核对。','组件编辑成本为 dC=D+B，关系成本为 dR=R△R′。类型或边界变化造成的旧关系删除与新关系加入分别计费。成本用于硬预算和同效用时的少改优先，不并入效用，也不奖励“接近初始图”。此处仅统计追加修正，BR-O已有编辑另行记账。累计编辑量与终态相对I0终态 G0 的净变化分别保存，以免反复修改同一对象时只报告最终差异。')
edit(590,'事务引入：把三个步骤与共同接受连接起来','原文步骤准确，但“完整修改状态”与不可拆分事务的关系可再明确。','以一次接受决定为主线，按冲突消除、受影响关系确定和整图判断展开。','读者能理解组件修改不能先行提交，纯关系动作也遵守同一接口。','组件修改与关系重建共同组成一次不可拆分的结构事务。算法先补齐删除集合以消除跨度冲突，再确定所有受端点变化影响的关系，最后对修改后的完整图作出一次接受决定。纯关系修改沿用同一事务接口，可在组件固定的条件下单独检验关系恢复能力。')
edit(594,'冲突闭合：说明窗口外对象为何仍须删除','原文结尾“虚假的局部可行性”较抽象，可直接对应忽略冲突的后果。','把内部兼容、窗口外冲突和预算超限分别写成明确条件。','局部窗口不会被误读为可以豁免整图冲突检查。','B 内部必须兼容，所有与新增对象冲突的旧组件都须进入 D，即使它们位于提议窗口之外。否则，新状态仍可能包含非法重叠。若补齐删除集合后超过预算，则拒绝提议，不能通过忽略窗口外冲突使其表面可行。')
edit(597,'依赖范围：区分端点闭合与两阶段的NONE','端点依赖域的定义和训练/推理NONE的区别在长句内快速切换。','先限定闭合处理的关系范围，再单独解释同一NONE名称在两阶段的含义。','不会把依赖闭合误作全部语义影响枚举，也不会将未预测关系当成不可修改金标。','本章以端点身份界定“依赖闭合”：组件被删除或替换后，所有引用旧对象的关系和新对象可能参与的关系共同进入决策，以免只计算组件收益而漏掉关系损失。“全部受影响关系”均指固定候选宇宙中的端点依赖域，并不包含组件选择变化后自动出现的所有新合法槽位。训练阶段的NONE来自既有标注，需要在改写后保持；本章的NONE则表示当前预测未选择正关系，其中可能存在漏检。因此，只要评分与约束允许，推理阶段可以将该状态改为一条关系。')
edit(602,'关系补全：将整图检查、扩域规则和闭合边界分层','该段同时给出最优性限定、事务外固定、扩域与语义边界，长句中的条件容易被忽略。','按求补全、完整比较、失效处理和范围限制展开，保留最小合法化及全部计费规则。','可以逐步判断何时扩大事务、何时拒绝，以及闭合并未承诺处理哪些槽位。','对每个 C′，算法先为受影响关系求合格的可行补全，只有取得最优性证书时才称为最优；随后比较完整的 G′=C′,R′，不先按组件分数提交 C′。事务外关系保持固定，整图仍须满足全局约束。若组件变化使已选事务外关系失效，则按最小合法化规则，将这些关系所在的完整槽位加入SR，重求解其全部合法标签，并对旧边删除和新边加入全部计费。扩域后仍不可行或超预算时，拒绝事务。该规则只处理已选旧关系的合法性，不自动纳入新合法但未选的全部非接触槽位。依赖闭合保证端点变化导致的关系失效不被漏记，不意味着自然语言的语义影响仅限一跳。')
edit(605,'计费过渡：从完整键自然引入参考事务','“规则如何进入效用、预算和事后计数”偏概括。','直接说明新旧键分别对应删增，再交代案例核对的三个具体对象。','后续案例与前文身份定义及计费规则的联系更紧密。','跨度或类型改变后，组件具有新的语义键：旧键关联的关系计为删除，新键参与的完整关系计为加入。4.4.3节通过真实文档上保存的事务，核对这一变化对应的效用增量、编辑预算和事后严格计数。')
edit(607,'事务来源：分开真实文本、冻结分数与运行路径','多种身份集中在开头，CPU参考事务与CPU规则案例容易被误认为同一实验。','按文档及路径、文字与分数来源、展示目的和独立案例区别说明。','读者能准确识别此处事务属于哪个条件，以及它与后文CPU诊断的关系。','本节使用AAEC测试文档essay077、种子29在Single路径中第1次已执行的CPU参考事务。组件文字取自原始语料，q来自9B主条件的冻结快照，用于展示类型替换与关系闭合的完整过程。4.6.4节essay098的线性CPU模型属于独立诊断，两者的计数分别报告。')
edit(610,'案例解释：按对象冲突、关系变化和身份结论展开','案例操作及身份结论并列，组件类型变化如何带动关系变化还可更连贯。','先说明同跨度类型替换的冲突，再逐项说明删增关系，最后解释字符不变仍换键的原因。','读者能够从表中具体对象理解完整键与依赖闭合。','原预测将[1483,1537)判为MajorClaim，原生标注类型为Claim。同跨度的新旧类型对象互相冲突，因此加入b新时必须删除b旧。事务随之删除两条指向旧对象的attacks，并加入a2指向新Claim的supports；a1、a2的文字和组件身份均保持不变。字符相同并不意味着对象身份相同，类型变化已产生新的完整键，旧关系不能沿用。')
edit(614,'事后计数：明确评价标签与失败成本的用途','金标用途和失败开销以分号相连，可更清楚地对应成功与拒绝两类结果。','先给出成功事务的严格计数，再分别说明标签用途及拒绝后的图/成本处理。','评价数据不参与接受判断的边界更醒目，也不会把拒绝理解为零计算成本。','事后严格计数中，组件TP/FP/FN由11/3/3变为12/2/2，关系由4/5/5变为5/3/4。金标仅用于这些事后计数。缺分和预算不足两种情况下均保留原图，但已发生的计算仍计入总开销。')
edit(617,'求解概览：从决策变量引出预算差异','共用条件与可行域差异紧接出现，差异原因可以更直接。','先说明两条路径分别决定什么，再指出累计与净编辑口径不同。','读者进入公式前即可把握两条路径并非仅有求解速度区别。','局部路径先固定通过冲突检查的组件提议，再补全受影响关系；全局路径则同时决定全部组件与关系。两者共用冻结评分、分项门和整图约束，但编辑预算分别按局部累计变化和全局净变化计算，因而具有不同的可行域。以下依次介绍局部执行、全局模型、方法性质和规模路由。')
edit(621,'局部目标：明确组件项何时可视为常数','“单次求解”与“不同提议比较”的范围可进一步明确。','直接将常数性质限定于固定组件提议下的关系求解。','读者不易误将组件效用从整个局部选择流程中删除。','固定组件提议后，组件项在本次关系求解中为常数；比较不同组件提议时，该项仍须保留。求解约束如下：')
edit(628,'求解规约：依次说明可行条件、破同分与超时复核','多个层次集中于一个长段，约束参与求解与返回后复核的区别不够突出。','先交代必须进入ILP的接受条件，再按目标优先级说明破同分，最后限定超时输出的身份。','最高分但违规不等于无可接受解，未完成破同分也不等于唯一输出，两点更易识别。','ILP同时限制 dC,dR 不超过各自剩余预算，并要求 ΔΦC,ΔΦR≥0。严格总效用门以固定正间隔和比较容差实现，提交前再次验证 ΔΦ>δ。这些条件必须参与求解：若先忽略条件求最高分，再发现结果违规，不能据此判定不存在可接受解。完整规约按最大主效用、最少实际编辑、最小完整状态规范键的顺序破同分，每一级求解均固定前级目标，不以任意小权重扰动主目标；比较容差写入配置。超时返回当前可行解（incumbent）时，重新核对全部约束，并记录前级最优及破同分是否完成。破同分未完成时，不声明唯一的规范化输出。数值容差和线程确定性纳入附录B的验收记录。')
edit(629,'动作邻域：按枚举与冲突闭合后的复核展开','动作定义、反向例外、窗口外删除和形态复核密集排列，实际动作与名义动作容易混淆。','先逐类说明提议如何生成，再统一说明冲突闭合如何改变真实形态和成本。','名义插入变成集合替换时为何不能进入单对象对照更加明确。','提议分为纯关系、插入、删除、替换、拆分和合并六类。纯关系提议枚举当前端点存在且合法的全部槽位，包括未选槽位；二元反向仅在冻结正逆槽位均存在且当前合法时将两者共同纳入SR，多源反向未作定义。插入从未选组件中枚举，删除从已选组件中枚举，替换由一个旧组件与一个新组件组成，允许类型或边界变化。拆分将一个旧组件替为两个兼容新组件，要求两个新跨度均位于旧跨度内，且首尾包络等于旧跨度；合并是其逆操作。每项提议先完成冲突闭合，将所有与新增组件冲突的旧对象纳入删除集合，包括名义窗口之外的对象，再按实际D,B复核动作形态、跨度条件及三对象上限。不符合五种声明形态的提议不进入主邻域；名义插入若实际变为2→1，单对象对照必须拒绝。端点变化引起的旧入边、出边及完整超边全部删除，新增完整关系逐项计费。动作与边界条件的验收记录见附录B.4。')
edit(630,'预算调度：区分外层额度与实际计算','外层尝试、阶段提交和关系补全的例外规则交织，容易把相同次数当成相同开销。','从共同计数单位出发，列明总额度，再解释原子方法与顺序方法的阶段差异。','预算数字的统计单位更明确，顺序方法何时还能完成关系阶段也更易查阅。','追加修正以外层提议为共同调度单位：每评估一个组件或纯关系提议记一次尝试，只要其中至少一个阶段成功提交，就记一次接受。每轮最多尝试32项、接受3项，共至多4轮；追加阶段总计最多128项尝试、12项接受，组件与关系累计编辑上限分别为24和96。这些额度从G0开始计算，不包含BR-O历史编辑；继承与追加阶段分别记录资源消耗，并共同计入完整推理成本。BR-J每次接受对应一次原子提交，顺序方法则最多对应两次阶段提交，因此阶段尝试、求解调用及提交另行计数，相同外层额度不代表相同计算量。顺序方法若已提交第一阶段，即使刚达到外层接受上限，仍可在剩余实际资源内完成配套关系阶段。批长与上述额度分别设置。')
edit(631,'批次提交：解释尝试额度与提交检查的区别','“提交已有合格项只检查……”较压缩，达到尝试上限后的处理不够直观。','先写评估与提交的先后，再明确两者消耗或检查的额度不同。','读者能理解已有合格项为何不因尝试额度耗尽而自动撤销。','每批从六类提议中轮转取项，依据冻结分数和剩余预算择优复核，再原子提交。新评估消耗尝试额度；已评估合格项提交时，只检查接受额度、编辑预算和实际资源，因此达到尝试上限不撤销这些候选。同一状态下不重复评估相同对象键，无法安全提交时返回最近的完整合法图。参考轨迹、缓存身份和资源规则见附录B。')
edit(677,'算法解释：把不修改返回、失败恢复和成本记录分开','子程序输入、no-op、失败类别及成本规则同时出现，算法后的解释负担较重。','先交代子程序边界，再解释no-op独立的原因，最后集中说明提交与失败账本。','合法回退、求解可行性和实际成本不再容易混为同一判断。','图4-2展示追加修正R_DC中集合局部BR-J子程序的数据流。其输入为I0终态G0或追加阶段最近的完整合法图，不重复执行前置BR-O；批次和失败语义由算法4-1与4-2规定。no-op独立于ILP，不要求严格增分，因为组件改变后的局部问题未必包含原图。候选构造、评分以及全部拒绝和超时尝试均计入实际资源，只有成功提交才增加追加阶段的语义编辑账本。提交失败时恢复组件、关系、语义键和缓存引用，已消耗的时间与调用仍保留在总成本中。缺少可行incumbent、数学不可行、评分失败和继承初始化失败分别记录，完整算法与日志接口见附录B。')
edit(679,'全局模型：明确不能只放开组件变量的原因','“完整规约”较抽象，模型转换的实质差异需要更突出。','将连续性依赖和预算参照变化作为两项明确原因。','从局部关系补全过渡到全局对象选择更自然，后续约束推导的必要性更清楚。','4.5.1节将组件固定为提议后的C′，只求解关系补全。全局路径同时选择全部组件和关系，还须相应调整约束，不能仅将固定组件变量改为自由变量。原因在于，CDCP源组连续性取决于中间组件是否被选中，编辑量与分项门也需改为相对初始图G0计算。本节据此给出全局模型的完整规约。')
edit(690,'可行域关系：按包含关系及反例方向解释','连续因果句同时说明局部终态属于全局域及逆向不成立，推理层次可以更清楚。','先推导局部终态满足全局限制，再说明全局解可能无法经局部单调路径到达。','读者能理解可行域不同的具体原因，而非仅记住两者不等价的结论。','（4）与局部路径的语义差别。局部事务以当前状态为参照检查分项门，编辑成本逐次累加。因而任一局部终态都满足相对G0的分项门，且净编辑不超过累计编辑，属于全局可行域。反过来，到达全局最优解的局部路径可能需要某一步分项效用下降，这一步会被局部接受门拒绝。因此，两条路径的可行域不等价，差异见表4-3。')
edit(698,'差分证明：写明共同对象抵消的原因','证明说明较压缩，固定评分与完整差集分别起什么作用可更直观。','分别解释不变对象抵消和改变关系进入差集。','公式的两项前提与实际事务构造形成明确对应。','同一对象的评分固定，因此两个状态共有的对象在差分中抵消；完整依赖重建则将所有改变的关系纳入差集。详细推导及评分发生变化时的适用边界见附录B.6。')
edit(702,'集合动作结论：说明构造证明的范围','两个否定句连续收束，理论例子实际证明了什么可以更突出。','先明确成组动作跨越的是单对象严格改进限制，再限定真实质量与邻域大小。','理论可达性与真实样本效果分开，避免把构造例子当成实验收益。','该例证明，在所构造的状态中，成组事务能够跨越单对象严格改进条件的限制；它不证明真实样本的F1必然提高。集合事务的能力仍受邻域大小约束，本章默认邻域无法跨越所有可能的局部障碍。')
edit(704,'终止性：将两个前提连成推理链','原文以两个短分句重复命题内容，推导关系可更自然。','用状态不可重复和状态总数有限解释接受序列为何有限，并保留预算停止的区别。','读者能直接理解终止性的依据，同时不会把资源耗尽当成同一证明。','每次接受都严格提高同一固定效用，因此不可能回到已访问状态；候选状态总数有限，接受序列也必然有限。完整证明及其与预算停止的区别见附录B.6。')
edit(707,'真实F1边界：从恒等式推到保证范围','“不能替代”“不能得到”等判断连写，真实计数未知与代理最优之间的关系略显跳跃。','先解释增益取决于哪些真实量，再说明校准无法给出逐事务保证，最后归纳方法所能保证的性质。','代理单调、逐次F1变化与全局F1最优三种结论不易混淆。','恒等式表明，真实增益由正确数与预测数的变化共同决定。推理时真实 ΔT 与 F 均未知，估计概率和固定 κ 不能替代这些量。即使候选级校准良好，也不能由此得到每次事务的误差上界。因此，本章只保证接受过程中代理效用单调，不保证真实F1单调或期望F1最优；即使在冻结候选宇宙内取得代理目标最优，也不等于取得真实F1的全局最优。')
edit(709,'路由引入：说明闭合规则与求解路径的关系','“依赖闭合规定……”较抽象，容易将方法名称等同于某一搜索实现。','把闭合解释为共同决策的对象范围，再引出按规模选择路径。','读者能理解完整方法为何可直接走全局路径，而无须执行集合局部循环。','依赖闭合规定一次修改中哪些关系必须共同决策，具体求解可以采用不同路径，并不要求所有输入都使用集合动作或局部搜索。默认按以下顺序路由，相关统计量与阈值在训练侧冻结：')
edit(711,'路由结果：把阈值规则与主实验落点相邻说明','通用规则、资源扫描和主测试路径挤在一起，主质量结果的适用范围不够醒目。','先列规模路由，再说明主测试实际进入的路径和独立局部消融的边界。','不会把小规模全局主结果外推为大候选池局部部署效果。','以n=|V|+|P|判定规模，受保护对象也计入其中。n≤2500时采用全局路径，其余默认采用单对象有界局部路径，集合局部BR-J作为独立可选配置。附录H保留500至4000变量的完整资源扫描。主测试690个文档—种子输入均进入全局路径，因此主质量结论对应这一求解规模；局部方法仅在共享快照上单独消融，其结果不能外推为大规模部署性能。')
edit(713,'局部用途：明确集合动作的开启条件','默认路径、可选动作、算法用途和规模限制连续陈述，主次关系可更清楚。','先说明默认单对象及集合开启依据，再解释算法仍用于哪些分析。','集合BR-J的理论与消融用途保留，同时避免误读为主实验必经环节。','局部路径默认使用单对象闭合，仅在训练侧拆分／合并诊断和受控比较提供支持时开启集合动作。算法4-1、4-2描述集合局部子程序，用于可达性分析及独立消融。小候选池直接全局求解，不经过局部循环；大候选池采用局部路径时，仍不保证真实F1提高。')
edit(714,'贡献归属：区分完整配置与子程序收益','几种方法身份和两项不能推断的结论紧密排列，可更突出追加比较的实际问题。','先说明公平比较需要报告的条件，再按R_DC、I1和BR-J层级解释比较含义。','I1相对I0的收益不会被误归为替代BR-O或集合动作的独立贡献。','即使候选、评分和时限相同，比较时也需报告预算语义与求解证书。R_DC表示追加阶段的依赖闭合决策及固定路由，完整I1由继承I0与R_DC串接而成，集合局部BR-J仅是可选子程序。因此，I1相对I0衡量的是在完整继承结果上继续修正的收益，不能用于判断R_DC替代BR-O的效果，也不能将总收益全部归于BR-J。')
edit(717,'对照设置：按共用起点、变化项和实际路由展开','方法缩写密集，固定条件与主路由说明之间缺少明显层次。','先确定同文档同种子的共同输入，再解释各配置的决策差异，最后限定主实验范围。','表中每个对照改变什么、完整I1实际采用什么路径更易理解。','对同一文档和种子，各结构修正对照固定T1、相应I0最终输出G0、候选快照、对象评分及合法化规则。I0保留G0，其他配置均从同一G0继续处理。RelationOnly固定组件，Sequential依次接受两层修改，Single在单对象动作中共同接受，SetLocal扩展集合动作，Global同时选择全部对象。主实验690个文档—种子输入的变量数均小于2500，I1全部采用Global路径；Single/SetLocal消融与主路由分别报告。')
edit(718,'补充对照：明确每项改动及空效应条件','多个配置以相同句式并列，NoRisk保留哪些门和MissingLow何时为空效应可更清楚。','逐项写明具体操作，将仍保留的限制与被取消的限制放在同一句中。','对照名不会代替操作定义，正常缺分为零时的解释边界更清晰。','Regenerate在相同追加模型调用与token上限内重新采样完整图并重排序。NoRisk取消开发保留约束，将δ降至数值正间隔，但仍保留合法性和两个分项门。NoCalibration改用未校准分数；MissingLow将缺失分数替为低值，正常评价缺分为零时仅用于检查空效应。')
edit(725,'主结果：减少重复统计套语，保留比较层级','“主要比较族的Holm校正后”反复出现，数值观察与结论容易被重复措辞遮蔽。','在开头明确校正口径，再按整体收益、组件可变收益与接受方式比较逐项解释。','显著与未显著的结果更容易对照，结论强度和所有数值保持不变。','固定T1后，I1相对I0的严格关系F1增量分别为3.38／5.68个百分点，均在主要比较族的Holm校正后达到统计显著性。RelationOnly固定组件时的得分为71.07和50.14，完整I1为71.63和50.77；允许组件修改后的点估计为正，但校正p值分别为0.2559和0.7031，未达到显著性标准。Single相对Sequential的差异同样未通过上述校正后的检验。集合动作是否带来额外贡献，则依据SetLocal与Single的独立比较判断。')
edit(726,'统计说明：解释区间与校正p值为何不矛盾','原文指出两者可并存，但读者需要自行联系各自的调整口径。','将区间未调整与p值按比较族校正直接连为原因解释。','读者不会因区间不含零就推翻多重比较后的判断。','表4-6报告的95%区间是未调整的单项区间，主要比较的p值则按包含14项比较的检验族作Holm校正。因此，单项区间不含零与Holm p超过0.05并不矛盾。逐文档联合计数、共同抽样索引及比较族清单均已提供，可据此重建每次重采样的差值。')
edit(727,'局部与全局结果：区分F1证据、最优证书与破同分','质量观察、路由依据和求解返回状态连续切换，最优证书可能被误读为唯一输出或最高真实F1。','先解释质量比较，再给出求解证书，最后明确未执行的破同分步骤。','代理最优不等于真实质量优势，也不等于多解情况下输出唯一，三层边界更清楚。','SetLocal与Single在当前候选池中得到相同计数，未观察到集合动作带来的额外F1增益。Global相对局部方法的差值，其单项区间均包含零。因此，全局路径的选择还考虑可行解证书、调度和资源成本，不预设其F1必然更高。主路径690个输入均获得代理目标值的最优证书，gap为0，正常评价无超时。主参考实现未执行三级词典序破同分，故不声明多解时的唯一语义输出；破同分及故障输入详见附录B。')
edit(728,'校准对照：把整体质量与误改代价分开解释','重生成、风险限制和概率校准三类结果连续罗列，校准为何另查TP损失的理由不够突出。','分别陈述主要比较，再用原TP损失说明仅看F1不足。','读者能够从具体误删数字理解评分校准的评价维度。','等预算重生成的点估计低于I1，但Holm校正后的主要比较未达到统计显著性。取消开发风险限制后，两语料的关系F1均与I1持平。评价概率校准还需检查误改代价：AAEC主配置／未校准条件分别损失原TP 23／33条，CDCP相应为4／4条。因此，校准效果不能只由F1判断，误改、校准误差及完整对象质量分别报告。')
edit(732,'覆盖链：逐层解释条件计数','“评分过门”“端点被选”的包含条件集中呈现，容易被理解为独立的几组数量。','按完整关系入池、评分通过、全部端点被选、终态严格命中的顺序解释。','表内逐步减少的数量有明确条件，完整超边命中标准也更突出。','计数单位为文档×种子×唯一语义对象。金标组件总数分别为3798和3078，完整关系总数为2427和756，候选正例数均不超过相应总数。“评分过门”以完整关系已入池为前提；“端点被选”进一步要求这些过门关系的全部端点出现在终态。最终TP再按原生完整对象核对，单源片段恢复不计作联合源命中。')
edit(733,'候选数量：明确实际求解规模的统计对象','保护结果、补充上限和求解空间边界并列，读者容易将理论枚举量混入实际候选量。','先陈述保护与截断的实际执行，再限定候选数量取自最终冻结池。','实际资源范围与覆盖评价各自指向什么更加清楚。','初始合法对象全部保留，无保护对象丢失。CDCP补充槽位按固定排序保留至多64个学习提案，并检查256个槽位的联合上限。候选数量以实际冻结池为准，截断前的枚举空间不计作已求解空间。候选上限属于协议的一部分，完整多源覆盖与最终恢复效果分别报告。')
edit(737,'逐文档影响：用实际下降记录解释经验约束','两语料重复“条文档—种子记录F1下降”，信息密度偏低。','保留分母与统计单位，将开发限制的适用范围接在真实下降记录后。','总体收益与个别文档受损可以同时理解，避免将5%经验约束读成逐例保证。','主配置中，AAEC有14/240条文档—种子记录的F1下降，CDCP有3/450条记录的F1下降。开发侧5%的原TP损失率限制依据汇总结果进行经验筛选，不能保证每篇测试文档都不发生误删或F1下降。终态净变化和追加阶段事务账本分别保存。')
edit(740,'评分质量：说明聚合口径和数据用途','种子均值、合计精确率和开发划分用途放在一起，读者需要多次切换统计层级。','先说明各列如何聚合，再比较校准部分与策略部分的用途。','均值与合计不会混用，两种开发数据也不会被误当作独立测试证据。','表4-9中，AUROC、AP、Brier及ECE取三个种子的指标均值，候选数和正例数取三种子合计，区域精确率依据合计正确数计算。校准部分用于概率校准，反映拟合内质量；策略部分未用于评分器拟合或概率校准，但用于阈值选择。因此，两部分结果均不能替代独立测试集上的评分质量评价。')
edit(745,'接受质量：区分决策池与实际新增关系','门限与新增正确率直接相接，筛选后的精确率为何不同还可更具体。','保留门限及计数，明确端点和预算选择改变了实际接受对象的组成。','读者不会将事务接受后的精确率当成整个决策池的评分质量。','AAEC与CDCP的关系门限分别为0.5和0.25，组件门限均为0.5。主配置新增关系中，AAEC有33/42正确，CDCP有20/24正确。实际接受对象还经过端点和预算条件的选择，因此其精确率不等同于整个决策池的精确率；错误新增和正确关系误删均纳入统计。')
edit(748,'缺分对照：分开正常评价与注入检查','主流程零缺分和故障检查成功相邻，容易把后者理解为已证明质量收益。','先解释MissingLow持平的直接原因，再说明注入检查验证的处理行为。','质量空效应与缺分保护机制是两类证据，不会互相替代。','主流程缺分率为0，裁剪、超长和数值异常均未造成遗漏评分，因而MissingLow与I1结果完全一致。这一对照不支持缺分处理带来质量增益的结论。另行执行的60项缺分注入检查覆盖NaN、未评估及对象缺失，均保留未知状态，并拒绝触及相应对象的事务。')
edit(751,'成本报告：按资源上限、阶段分解和计时身份展开','共享编码、阶段文件和CPU/GPU计时连续出现，总成本如何得到需要读者自行整理。','先交代共同追加资源，再说明总成本求和及共享计数，最后说明日志对应与计时分离。','端到端成本的组成和比较边界更透明，不会将CPU求解时间混入GPU时延。','I1与Regenerate均从相应I0终态G0继续，追加两次文本处理的累计输入上限为8192、输出上限为2048 token。表4-12分列生成与重排、共同合法化、BR-O、追加生成、提案、评分和追加求解，端到端成本为各阶段之和，发生回退时也保留已耗成本。P/S共享编码仅计一次。inherited_stages_v9.jsonl对应保存Grank、Gpre和G0，inference_cost_complete按文档区分共享I0与追加阶段。各阶段记录均按9B配置逐项建立，BR-O成本不从未分解的总值反推；CPU求解计时另存于solver_counts，不与GPU时延混合汇总。')
edit(753,'规则诊断：明确固定规则、真实输出与方法范围','文档身份、模型、预测数量和处理规则密集排列，实际操作的顺序可以更清楚。','按诊断来源、初始输出、规则和评价边界组织，不改动文档哈希及任何数值。','读者能复述该诊断实际做了什么，也不会把它误作完整方法的执行结果。','本节使用CPU程序的真实输出分析固定规则的修正效果。官方测试文档essay098的全文哈希为f68e231bdf7576fe87d57e801350c2b0ef2f513d51e29938b223671a392f528c，组件与关系模型由CPU-BIO-SGD在训练侧拟合。种子17的原始输出包含1条正确关系和54条误边。后处理依据训练侧类型—关系签名，为同一预测源保留中点距离最近的目标，同距时按语义键排序；全部规则在评价前固定。删边不依赖测试金标，此处也未执行本章完整对象评分与ILP事务。')
edit(759,'诊断结论：把观察结果与系统身份对应','多个限制紧接结论，诊断用途与局限的主次关系可更自然。','先说明固定规则减少过量连边，再交代它属于低质量CPU模型的独立诊断。','案例能够支持的观察保留，同时清楚限定其不代表主系统或完整端点恢复。','该案例显示固定后处理能够减少过量连边。由于CPU模型整体质量较低，其逐文档输出作为独立诊断保存；这一结果不属于主表Qwen系统的单文档评价，也不能证明完整端点恢复。')
edit(760,'失败案例：突出误边减少仍损失正确关系','数据充分，但失败结论与保留原结果的说明略显割裂。','围绕固定规则误删正确关系这一事件，连接计数变化、F1下降及报告方式。','失败原因更直接，读者不会只看误边减少就判定修正有效。','种子29的essay098输出原本也命中表4-14的正确关系，固定规则却将其删除，使TP/FP/FN由1/45/5变为0/17/6，关系F1降至0。虽然误边减少28条，正确关系的损失仍导致该例失败。这里保留实际结果，未重新调整阈值，也未借助金标恢复关系。')
edit(761,'案例归属：说明事后选例与完整记录的关系','相同文档范围、独立运行身份和主条件账本多次切换，容易混淆样本与预测来源。','先限定选例用途，再明确文档范围相同不等于运行和预测集合相同。','CPU示例与主实验记录的关系可直接核对，避免用附加诊断替代主结果证据。','两个CPU线性模型案例均在固定规则处理完成后事后选取，只用于解释成功与失败机制。其完整690条记录与主条件690个文档—种子输入覆盖相同文档范围，但运行ID和预测集合彼此独立。主条件另存冻结候选、评分、事务日志及事后计数，第4.4.3节直接引用其中一条事务；规则诊断不替代主条件账本。')
edit(764,'原生超边：从语义内容连接到完整匹配要求','“来源分别是……”的指代不够具体，完整对象要求与例子联系可以更紧密。','点明两个value各自表达的依据，再解释为什么单源预测不能命中双源关系。','联合源作为一个标注对象的含义更直观，案例用途也保持明确。','两个value分别表达偏好电子邮件和无法确认邮件送达，共同支持policy，原生标注将其记为完整双源reason。引文保留原有标点及大小写。评价器同时匹配完整源集合、目标和标签，因此预测一条单源关系不能抵消该超边的FN。此例仅解释原生任务身份，不附加模型评分或修复输出。')
edit(769,'跨格式案例：分别说明核对对象、数据划分和用途','两语料的内容限定、字段格式及划分状态紧密串接，信息归属略显拥挤。','先说明各自核对内容，再用“分别”对应数据划分，最后交代不进入主表的用途。','读者可明确各案例的来源与评价范围，避免将无官方划分的数据写成测试集。','CasiMedicos引文涉及诊断线索，本文只核对原文、跨度及论辩标注，不判断医疗结论是否正确。ArgUNSC的premise与claim保留原字段大小写和关系方向。两例分别取自train与unsplit_author_release；ArgUNSC没有官方划分，因而不称为测试集。它们用于跨格式结构诊断，不并入AAEC／CDCP主效果表。')
edit(771,'弱评分条件：先交代独立身份，再说明策略回退','“保留”多次重复，条件失效、强制诊断和主条件差异不够分层。','依次说明保留快照的用途、触发回退的规则和强制修正的诊断身份。','不会将强制修正结果当成实际策略输出，也不会把不同条件差值作单因素归因。','弱评分条件v0沿用原版本初始图和评分快照，用于独立分析评分条件失效，与Qwen3.5-9B主条件分别记录实验身份。当κR=1时，该条件不满足开发侧原TP损失≤5%的规则，因此实际策略保留初始图，关系F1为39.81；表中的强制修正仅用于条件诊断。v0与Qwen3.5-9B主条件同时存在骨干设定、数量协议和评分快照差异，两者差值不作单因素效果解释。')
edit(775,'回退解释：把评分指标与实际接受判断联系起来','“共同决定可接受修改”较抽象，为何仍需检查决策区域可更明确。','保留四项影响因素，再指出全局平均指标无法替代局部决策和TP保留检查。','读者能够理解评分看似改善时策略仍可能需要回退。','这些结果表明，能否接受修正取决于评分排序、概率标度、候选组成和决策门限的共同作用。平均AUROC或整体ECE改善，仍不足以判断具体修正是否可接受，还须检查决策区域表现与原TP保留情况。主配置在两种语料上的收益和v0的回退结果分别报告。')
edit(779,'章末收束：按方法、结果和限制总结','方法规约、统计结果、可行域与案例身份并列，收束重点较分散。','先概括共同决策机制，再报告已支持的整体收益，随后说明路径比较与证据来源边界。','本章贡献和仍需谨慎解释的比较更清楚，结论强度与正文一致。','本章以统一事务处理组件修改及其引起的关系身份变化，并明确冻结评分、完整差集、分项门和失败回退规则。固定T1时，两种语料的追加推理增量均在主要比较族的Holm校正后达到统计显著性，其他对照则需依据各自区间与检验解释。局部累计编辑与全局净编辑对应不同可行域，路径差异不能全部归于搜索效率。主条件、真实文档事务和独立CPU案例分别记录来源及返回状态，为上述分析提供各自对应的依据。')
edit(780,'章节衔接：明确下一章综合比较的两阶段','“两阶段”在短过渡句中指代较远，需要读者回溯。','直接点明训练增强与推理修正，保持原有综合分析任务。','第四章自然过渡到第五章，读者无需回看即可知道综合分析的对象。','第五章将结合训练增强与推理修正，综合分析两阶段的关系恢复、交互作用及剩余错误。')

